// Converts an Overpass JSON extract into a MetroGraph network file.
//
//   metrograph_import <overpass.json> <settings.tsv> <out.graph>
//
// The import log (notes and warnings) goes to stderr; warnings deserve a human look before the
// generated file is committed.

#include <fstream>
#include <iostream>
#include <string>

#include "metrograph/network.hpp"
#include "metrograph/osm_import.hpp"

int main(int argc, char** argv) {
    if (argc != 4) {
        std::cerr << "usage: metrograph_import <overpass.json> <settings.tsv> <out.graph>\n";
        return 2;
    }
    const std::string json_path = argv[1];
    const std::string config_path = argv[2];
    const std::string out_path = argv[3];

    try {
        std::ifstream config_file(config_path, std::ios::binary);
        if (!config_file) {
            throw std::runtime_error("cannot open settings file '" + config_path + "'");
        }
        const auto config = metrograph::osm::load_config(config_file);

        std::ifstream json(json_path, std::ios::binary);
        if (!json) {
            throw std::runtime_error("cannot open extract '" + json_path + "'");
        }
        const auto result = metrograph::osm::import_overpass(json, config);

        for (const auto& note : result.notes) {
            std::cerr << "note: " << note << '\n';
        }
        for (const auto& warning : result.warnings) {
            std::cerr << "warning: " << warning << '\n';
        }

        std::ofstream out(out_path, std::ios::binary | std::ios::trunc);
        if (!out) {
            throw std::runtime_error("cannot write '" + out_path + "'");
        }
        out << "# Generated by metrograph_import from " << json_path << " with " << config_path << ".\n"
            << "# Do not edit by hand; regenerate instead. Data (c) OpenStreetMap contributors, ODbL.\n";
        metrograph::save_network(result.network, out);
        out.close();
        if (!out) {
            throw std::runtime_error("failed while writing '" + out_path + "'");
        }

        const auto& n = result.network;
        std::cerr << "wrote " << out_path << ": " << n.stations().size() << " stations, " << n.lines().size()
                  << " lines, " << n.segments().size() << " segments, " << n.walkways().size() << " walkways, "
                  << result.warnings.size() << " warning(s)\n";
        return 0;
    } catch (const std::exception& e) {
        std::cerr << "error: " << e.what() << '\n';
        return 1;
    }
}
